import { expect, expectStatus, test } from "../../fixtures";

test("A vendor under review cannot have its contact email changed", { tag: "@VEN-09" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const { vendor } = await factory.vendorInReview({ as: "member" });
  expect(vendor.status, "vendor is in review before the edit").toBe("in_review");

  // Act
  const response = await member.patch(`/api/vendors/${vendor.id}`, {
    data: { contact_email: "billing@acmefreight.example" },
  });

  // Assert
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_locked");

  // Re-read the stored record: the refused edit must not have been saved.
  const stored = await expectStatus<{ contact_email: string; status: string }>(
    await member.get(`/api/vendors/${vendor.id}`),
    200,
  );
  expect(stored.status).toBe("in_review");
  expect(stored.contact_email).toBe("ops@vendor.example");
});
